/**
 * exports use cases (PATTERNS §7), S9-01: portal connections, their selection rule and per-property choices.
 * `(ctx: Ctx, input) → DTO`. Authorize with `assertCan`, read and write through `./repo`, emit outbox events in the
 * same transaction, never call the network. Portal feeds are written by S9-02 and generated by S9-03.
 */
import {
  type CreatePortalConnectionInput,
  type ListPortalOverridesQuery,
  MAX_CONNECTION_OVERRIDES,
  MAX_PORTAL_CONNECTIONS,
  type PageQuery,
  type PortalChannelList,
  type PortalConnectionDto,
  type PortalConnectionPage,
  type PortalConnectionParams,
  type PortalConnectionSecretDto,
  type PortalOverridePage,
  type PortalSelectionPage,
  type PortalSelectionQuery,
  type SetPortalOverridesInput,
  type UpdatePortalConnectionInput,
} from '@inmolink/contracts';
import type { Tx } from '@inmolink/db';
import { clock } from '@inmolink/platform/clock';
import { hmacSha256, newToken } from '@inmolink/platform/crypto';
import { AppError } from '@inmolink/platform/errors';
import { newId } from '@inmolink/platform/ids';
import { emit } from '@inmolink/platform/outbox';
import { z } from 'zod';
import type { Ctx } from '../../context';
import { decodeCursor, toPage } from '../../pagination';
import * as agencies from '../agencies';
import * as compliance from '../compliance';
import * as properties from '../properties';
import { encryptCredentials, tokenKey } from './config';
import { exportsEvents } from './events';
import { assertCan } from './policy';
import * as repo from './repo';
import { ruleOf, type SelectionRule, selectionBatch, selectionPage } from './selection';

const TOKEN_PURPOSE = 'exports.feed-token';
const tokenHashOf = (token: string) => hmacSha256(tokenKey(), TOKEN_PURPOSE, token);

/** The hash a feed token is stored as (the feed server, S9-04, hashes the presented token the same way). */
export const portalFeedTokenHash = tokenHashOf;

function toDto(row: repo.ConnectionRow, counts: { include: number; exclude: number } | undefined): PortalConnectionDto {
  return {
    id: row.id,
    channelCode: row.channelCode,
    name: row.name,
    enabled: row.enabled,
    selection: { mode: row.selectionMode, tag: row.selectionTag },
    credentialKeys: row.credentialKeys,
    tokenActive: row.revokedAt === null,
    tokenHint: row.tokenHint,
    tokenCreatedAt: row.tokenCreatedAt.toISOString(),
    includeCount: counts?.include ?? 0,
    excludeCount: counts?.exclude ?? 0,
    version: row.version,
    createdAt: row.createdAt.toISOString(),
    updatedAt: row.updatedAt.toISOString(),
  };
}

async function dtoOf(tx: Tx, row: repo.ConnectionRow): Promise<PortalConnectionDto> {
  const counts = await repo.overrideCounts(tx, row.agencyId, [row.id]);
  return toDto(row, counts.get(row.id));
}

async function loadConnection(ctx: Ctx, id: string, forUpdate = false): Promise<repo.ConnectionRow> {
  const row = await repo.getConnection(ctx.tx, ctx.tenant.agencyId, id, forUpdate);
  if (!row) throw new AppError('PORTAL_CONNECTION_NOT_FOUND');
  return row;
}

function requireUser(ctx: Ctx): string {
  if (ctx.actor.kind !== 'user') throw new AppError('FORBIDDEN');
  return ctx.actor.userId;
}

function assertCredentialKeys(channel: repo.ChannelRow, credentials: Record<string, string>): void {
  const unknown = Object.keys(credentials).filter((k) => !channel.credentialFields.includes(k));
  if (unknown.length > 0) {
    throw new AppError('VALIDATION_FAILED', { field: 'credentials', allowed: channel.credentialFields });
  }
}

/** A keyset cursor for listing ids: a UUID (the id the previous page ended at). */
function listingCursor(cursor: string | undefined): string | null {
  if (cursor === undefined) return null;
  if (!z.uuid().safeParse(cursor).success) throw new AppError('VALIDATION_FAILED', { field: 'cursor' });
  return cursor.toLowerCase();
}

// ── Catalog ───────────────────────────────────────────────────────────────────────────────────────────────────

/** The portals an agency can connect (and the ones still planned). */
export async function listChannels(ctx: Ctx): Promise<PortalChannelList> {
  assertCan(ctx, 'exports.read');
  return { items: await repo.listChannels(ctx.tx) };
}

/**
 * The catalog (S9-01, PLAN §3 #19): Kyero, thinkSPAIN, A Place in the Sun and generic XML are available; idealista and
 * Fotocasa are listed for later (partner approval). `credentialFields` are placeholders until each writer (S9-02)
 * documents what its portal needs.
 */
export const PORTAL_CHANNEL_CATALOG: readonly (repo.ChannelRow & { position: number })[] = [
  { code: 'kyero', name: 'Kyero', status: 'AVAILABLE', credentialFields: [], position: 10 },
  { code: 'thinkspain', name: 'thinkSPAIN', status: 'AVAILABLE', credentialFields: ['agentId'], position: 20 },
  {
    code: 'a-place-in-the-sun',
    name: 'A Place in the Sun',
    status: 'AVAILABLE',
    credentialFields: ['accountId'],
    position: 30,
  },
  { code: 'generic-xml', name: 'Generic XML', status: 'AVAILABLE', credentialFields: [], position: 40 },
  {
    code: 'idealista',
    name: 'idealista',
    status: 'PLANNED',
    credentialFields: ['clientId', 'clientSecret'],
    position: 50,
  },
  {
    code: 'fotocasa',
    name: 'Fotocasa',
    status: 'PLANNED',
    credentialFields: ['clientId', 'clientSecret'],
    position: 60,
  },
];

/** Writes the catalog (`withSystem`: `pnpm exports:sync-channels`, tests). Idempotent. */
export const syncPortalChannels = (tx: Tx) => repo.upsertChannels(tx, PORTAL_CHANNEL_CATALOG);

// ── Connections ───────────────────────────────────────────────────────────────────────────────────────────────

export async function listConnections(ctx: Ctx, q: PageQuery): Promise<PortalConnectionPage> {
  assertCan(ctx, 'exports.read');
  const rows = await repo.listConnections(ctx.tx, ctx.tenant.agencyId, {
    limit: q.limit,
    cursor: decodeCursor(q.cursor),
  });
  const page = rows.slice(0, q.limit);
  const counts = await repo.overrideCounts(
    ctx.tx,
    ctx.tenant.agencyId,
    page.map((r) => r.id),
  );
  return toPage(
    rows,
    q.limit,
    (r) => ({ at: r.createdAt, id: r.id }),
    (r) => toDto(r, counts.get(r.id)),
  );
}

export async function getConnection(ctx: Ctx, params: PortalConnectionParams): Promise<PortalConnectionDto> {
  assertCan(ctx, 'exports.read');
  return dtoOf(ctx.tx, await loadConnection(ctx, params.connectionId));
}

/** Adds a connection (agency admins; at most `MAX_PORTAL_CONNECTIONS`). Its feed token is in the answer only. */
export async function createConnection(
  ctx: Ctx,
  input: CreatePortalConnectionInput,
): Promise<PortalConnectionSecretDto> {
  assertCan(ctx, 'exports.manage');
  const userId = requireUser(ctx);
  const { agencyId } = ctx.tenant;
  const channel = await repo.getChannel(ctx.tx, input.channelCode);
  if (channel?.status !== 'AVAILABLE') throw new AppError('PORTAL_CHANNEL_UNAVAILABLE');
  if (input.credentials) assertCredentialKeys(channel, input.credentials);
  // Serialises concurrent creates of the agency, so the cap and the name check cannot be raced.
  await agencies.lockAgencyStatus(ctx.tx, agencyId, 'update');
  if ((await repo.countConnections(ctx.tx, agencyId)) >= MAX_PORTAL_CONNECTIONS) {
    throw new AppError('PORTAL_CONNECTION_LIMIT_REACHED', { limit: MAX_PORTAL_CONNECTIONS });
  }
  if (await repo.nameTaken(ctx.tx, agencyId, input.channelCode, input.name)) {
    throw new AppError('PORTAL_CONNECTION_NAME_TAKEN');
  }
  const id = newId();
  const token = newToken(32);
  const row = await repo.insertConnection(ctx.tx, {
    id,
    agencyId,
    channelCode: input.channelCode,
    name: input.name,
    selectionMode: input.selection.mode,
    selectionTag: input.selection.tag,
    credentialsEnc: input.credentials ? encryptCredentials(agencyId, id, input.credentials) : null,
    credentialKeys: input.credentials ? Object.keys(input.credentials).sort() : [],
    tokenHash: tokenHashOf(token),
    tokenHint: token.slice(-4),
    createdBy: userId,
    now: clock.now(),
  });
  await emit(
    ctx.tx,
    exportsEvents.connectionChanged({ connectionId: id, agencyId, action: 'CREATED', version: row.version }),
  );
  await compliance.audit(
    ctx,
    'exports.connection.created',
    { type: 'portalConnection', id },
    { channel: input.channelCode, mode: input.selection.mode },
  );
  return { connection: toDto(row, undefined), token };
}

/**
 * Changes a connection (agency admins), on the version the edit was made on (`VERSION_CONFLICT` otherwise): name,
 * on/off, selection rule, credentials (replaced, or removed with `null`).
 */
export async function updateConnection(
  ctx: Ctx,
  params: PortalConnectionParams,
  input: UpdatePortalConnectionInput,
): Promise<PortalConnectionDto> {
  assertCan(ctx, 'exports.manage');
  const { agencyId } = ctx.tenant;
  const current = await loadConnection(ctx, params.connectionId, true);
  if (current.version !== input.version) throw new AppError('VERSION_CONFLICT', { current: current.version });
  const name = input.name ?? current.name;
  if (name !== current.name && (await repo.nameTaken(ctx.tx, agencyId, current.channelCode, name, current.id))) {
    throw new AppError('PORTAL_CONNECTION_NAME_TAKEN');
  }
  let credentialsEnc = current.credentialsEnc;
  let credentialKeys = current.credentialKeys;
  if (input.credentials !== undefined) {
    if (input.credentials === null) {
      credentialsEnc = null;
      credentialKeys = [];
    } else {
      // A portal that left the catalog (or is not available) accepts no credentials: never skip the allowlist.
      const channel = await repo.getChannel(ctx.tx, current.channelCode);
      if (channel?.status !== 'AVAILABLE') throw new AppError('PORTAL_CHANNEL_UNAVAILABLE');
      assertCredentialKeys(channel, input.credentials);
      credentialsEnc = encryptCredentials(agencyId, current.id, input.credentials);
      credentialKeys = Object.keys(input.credentials).sort();
    }
  }
  const next: repo.ConnectionFields = {
    name,
    enabled: input.enabled ?? current.enabled,
    selectionMode: input.selection?.mode ?? current.selectionMode,
    selectionTag: input.selection ? input.selection.tag : current.selectionTag,
    credentialsEnc,
    credentialKeys,
  };
  const changed = [
    next.name !== current.name && 'name',
    next.enabled !== current.enabled && 'enabled',
    (next.selectionMode !== current.selectionMode || next.selectionTag !== current.selectionTag) && 'selection',
    next.credentialsEnc !== current.credentialsEnc && 'credentials',
  ].filter((f): f is string => typeof f === 'string');
  if (changed.length === 0) return dtoOf(ctx.tx, current);
  const row = await repo.updateConnection(ctx.tx, agencyId, current.id, next, clock.now());
  await emit(
    ctx.tx,
    exportsEvents.connectionChanged({ connectionId: row.id, agencyId, action: 'UPDATED', version: row.version }),
  );
  await compliance.audit(
    ctx,
    'exports.connection.changed',
    { type: 'portalConnection', id: row.id },
    { fields: changed },
  );
  return dtoOf(ctx.tx, row);
}

/** New feed token (agency admins): shown once; the previous one stops working at once. Revives a revoked token. */
export async function rotateConnectionToken(
  ctx: Ctx,
  params: PortalConnectionParams,
): Promise<PortalConnectionSecretDto> {
  assertCan(ctx, 'exports.manage');
  const { agencyId } = ctx.tenant;
  const current = await loadConnection(ctx, params.connectionId, true);
  const token = newToken(32);
  const row = await repo.setToken(ctx.tx, agencyId, current.id, {
    tokenHash: tokenHashOf(token),
    tokenHint: token.slice(-4),
    now: clock.now(),
  });
  await emit(
    ctx.tx,
    exportsEvents.connectionChanged({ connectionId: row.id, agencyId, action: 'TOKEN_ROTATED', version: row.version }),
  );
  await compliance.audit(ctx, 'exports.connection.tokenRotated', { type: 'portalConnection', id: row.id }, {});
  return { connection: await dtoOf(ctx.tx, row), token };
}

/** Turns the feed URL off (agency admins) until the token is rotated. */
export async function revokeConnectionToken(ctx: Ctx, params: PortalConnectionParams): Promise<PortalConnectionDto> {
  assertCan(ctx, 'exports.manage');
  const { agencyId } = ctx.tenant;
  const current = await loadConnection(ctx, params.connectionId, true);
  if (current.revokedAt !== null) return dtoOf(ctx.tx, current);
  const row = await repo.revokeToken(ctx.tx, agencyId, current.id, clock.now());
  await emit(
    ctx.tx,
    exportsEvents.connectionChanged({ connectionId: row.id, agencyId, action: 'TOKEN_REVOKED', version: row.version }),
  );
  await compliance.audit(ctx, 'exports.connection.tokenRevoked', { type: 'portalConnection', id: row.id }, {});
  return dtoOf(ctx.tx, row);
}

export async function deleteConnection(ctx: Ctx, params: PortalConnectionParams): Promise<void> {
  assertCan(ctx, 'exports.manage');
  const { agencyId } = ctx.tenant;
  const current = await loadConnection(ctx, params.connectionId, true);
  await repo.deleteConnection(ctx.tx, agencyId, current.id);
  await emit(
    ctx.tx,
    exportsEvents.connectionChanged({
      connectionId: current.id,
      agencyId,
      action: 'DELETED',
      version: current.version + 1,
    }),
  );
  await compliance.audit(ctx, 'exports.connection.deleted', { type: 'portalConnection', id: current.id }, {});
}

// ── Per-property choices ──────────────────────────────────────────────────────────────────────────────────────

/**
 * Sets or clears INCLUDE / EXCLUDE for up to `MAX_OVERRIDES_PER_REQUEST` listings of the agency, named by id or by
 * reference (agency admins). A choice never publishes a listing: one that is not ACTIVE and PUBLIC stays out of the
 * feed. At most `MAX_CONNECTION_OVERRIDES` per connection. References are resolved here in one statement; one that
 * matches none of the agency's listings refuses the request (`LISTING_NOT_FOUND`, `details.refs`). Clearing a choice
 * needs no live listing (a deleted or withdrawn one can be cleared). Nothing changed: no version, event or audit.
 */
export async function setOverrides(
  ctx: Ctx,
  params: PortalConnectionParams,
  input: SetPortalOverridesInput,
): Promise<PortalConnectionDto> {
  assertCan(ctx, 'exports.manage');
  const userId = requireUser(ctx);
  const { agencyId } = ctx.tenant;
  const connection = await loadConnection(ctx, params.connectionId, true);

  const refs = input.items.flatMap((i) => (i.ref === undefined ? [] : [i.ref]));
  const byRef = new Map(
    (await properties.listingIdsByRefs(ctx.tx, agencyId, refs)).map((r) => [r.ref.toUpperCase(), r.id]),
  );
  const unmatched = refs.filter((r) => !byRef.has(r.toUpperCase()));
  if (unmatched.length > 0) throw new AppError('LISTING_NOT_FOUND', { refs: unmatched });
  const items = input.items.map((i) => ({
    propertyId: i.propertyId ?? (byRef.get((i.ref as string).toUpperCase()) as string),
    action: i.action,
    byId: i.propertyId !== undefined,
  }));
  const ids = items.map((i) => i.propertyId);
  if (new Set(ids).size !== ids.length) throw new AppError('VALIDATION_FAILED', { field: 'items' });
  // Listings to choose by id must be the agency's own, live ones; clearing needs nothing (the delete is this connection's).
  const chosenById = items.filter((i) => i.action !== null && i.byId).map((i) => i.propertyId);
  const own = new Set(await properties.ownListingIds(ctx.tx, agencyId, chosenById));
  const unknown = chosenById.filter((id) => !own.has(id));
  if (unknown.length > 0) throw new AppError('LISTING_NOT_FOUND', { ids: unknown });

  const existing = new Map((await repo.overridesOf(ctx.tx, connection.id, ids)).map((o) => [o.propertyId, o.action]));
  const setItems = items.filter((i) => i.action !== null && existing.get(i.propertyId) !== i.action);
  const clearIds = items.filter((i) => i.action === null && existing.has(i.propertyId)).map((i) => i.propertyId);
  if (setItems.length === 0 && clearIds.length === 0) return dtoOf(ctx.tx, connection);
  const added = setItems.filter((i) => !existing.has(i.propertyId)).length;
  if (added > 0) {
    const counts = (await repo.overrideCounts(ctx.tx, agencyId, [connection.id])).get(connection.id);
    const total = (counts?.include ?? 0) + (counts?.exclude ?? 0) + added - clearIds.length;
    if (total > MAX_CONNECTION_OVERRIDES) {
      throw new AppError('PORTAL_OVERRIDE_LIMIT_REACHED', { limit: MAX_CONNECTION_OVERRIDES });
    }
  }
  const now = clock.now();
  await repo.upsertOverrides(
    ctx.tx,
    setItems.map((i) => ({
      connectionId: connection.id,
      propertyId: i.propertyId,
      agencyId,
      action: i.action as repo.OverrideAction,
      createdBy: userId,
      now,
    })),
  );
  await repo.deleteOverrides(ctx.tx, connection.id, clearIds);
  const row = await repo.touchConnection(ctx.tx, agencyId, connection.id, now);
  await emit(
    ctx.tx,
    exportsEvents.connectionChanged({
      connectionId: row.id,
      agencyId,
      action: 'SELECTION_CHANGED',
      version: row.version,
    }),
  );
  await compliance.audit(
    ctx,
    'exports.connection.selectionChanged',
    { type: 'portalConnection', id: row.id },
    { set: setItems.length, cleared: clearIds.length },
  );
  return dtoOf(ctx.tx, row);
}

/** The connection's per-property choices, by listing id (keyset), with the listings' references. */
export async function listOverrides(
  ctx: Ctx,
  params: PortalConnectionParams,
  q: ListPortalOverridesQuery,
): Promise<PortalOverridePage> {
  assertCan(ctx, 'exports.read');
  const connection = await loadConnection(ctx, params.connectionId);
  const rows = await repo.overrideIdPage(ctx.tx, connection.id, {
    action: q.action ?? null,
    after: listingCursor(q.cursor),
    limit: q.limit + 1,
  });
  const page = rows.slice(0, q.limit);
  const refs = new Map(
    (
      await properties.listingRefs(
        ctx.tx,
        ctx.tenant.agencyId,
        page.map((r) => r.propertyId),
      )
    ).map((r) => [r.id, r.ref]),
  );
  return {
    items: page.map((r) => ({ propertyId: r.propertyId, ref: refs.get(r.propertyId) ?? null, action: r.action })),
    nextCursor: rows.length > q.limit ? (page.at(-1)?.propertyId ?? null) : null,
  };
}

// ── Selection ─────────────────────────────────────────────────────────────────────────────────────────────────

/**
 * A batch of the listing ids a connection sends, ascending after `cursor` (the id the previous batch ended at; a
 * non-UUID cursor is `VALIDATION_FAILED`): the reusable API of the selection for writers. Loop until `nextCursor` is
 * null. A batch is short only at the end — or when many EXCLUDEs thinned it (at most 10 pages are read per call; then
 * `nextCursor` continues). Nothing is read beyond the batch.
 */
export async function selectListings(
  ctx: Ctx,
  connectionId: string,
  opts: { cursor?: string | null; limit?: number } = {},
): Promise<{ ids: string[]; nextCursor: string | null }> {
  assertCan(ctx, 'exports.read');
  const cursor = listingCursor(opts.cursor ?? undefined);
  const connection = await loadConnection(ctx, connectionId);
  const page = await selectionBatch(ctx.tx, ruleOf(connection), cursor, opts.limit);
  return { ids: page.ids, nextCursor: page.next };
}

/** A connection as the generator (worker) needs it: what to send to which portal, and the version it read it at. */
export interface WorkerConnection {
  id: string;
  agencyId: string;
  channelCode: string;
  enabled: boolean;
  /** Set: the feed token was revoked (nothing to serve). */
  revokedAt: Date | null;
  /** The connection's version when read: a run compares it with a fresh read at the end (a change re-queues it). */
  version: number;
  rule: SelectionRule;
}

/** Worker side (`withSystem`, no ctx): a connection of a known agency, read once; null: no such connection. */
export async function connectionForWorker(
  tx: Tx,
  agencyId: string,
  connectionId: string,
): Promise<WorkerConnection | null> {
  const row = await repo.getConnection(tx, agencyId, connectionId);
  if (!row) return null;
  return {
    id: row.id,
    agencyId: row.agencyId,
    channelCode: row.channelCode,
    enabled: row.enabled,
    revokedAt: row.revokedAt,
    version: row.version,
    rule: ruleOf(row),
  };
}

/**
 * Worker side: the next batch of a loaded connection's selection (same rules and limits as `selectListings`), with
 * no read of the connection itself — every batch of a run uses the one rule it was loaded with.
 */
export async function selectConnectionListings(
  tx: Tx,
  connection: Pick<WorkerConnection, 'rule'>,
  opts: { cursor?: string | null; limit?: number } = {},
): Promise<{ ids: string[]; nextCursor: string | null }> {
  const page = await selectionBatch(tx, connection.rule, opts.cursor ?? null, opts.limit);
  return { ids: page.ids, nextCursor: page.next };
}

/** Dashboard preview: one page (short is fine; `nextCursor` continues) of the listings the connection sends now. */
export async function previewSelection(
  ctx: Ctx,
  params: PortalConnectionParams,
  q: PortalSelectionQuery,
): Promise<PortalSelectionPage> {
  assertCan(ctx, 'exports.read');
  const cursor = listingCursor(q.cursor);
  const connection = await loadConnection(ctx, params.connectionId);
  const page = await selectionPage(ctx.tx, ruleOf(connection), cursor, q.limit);
  const refs = new Map((await properties.listingRefs(ctx.tx, ctx.tenant.agencyId, page.ids)).map((r) => [r.id, r.ref]));
  return {
    items: page.ids.map((id) => ({ propertyId: id, ref: refs.get(id) ?? null })),
    nextCursor: page.next,
  };
}
